export function stepOf(task: string): Step | undefined {
    return STEPS.find((s) => s.task === task) ?? STEPS.find((s) => s.also?.includes(task));
}
export const writerSteps = (): Step[] => STEPS.filter((s) => s.writes);
export interface StepChoice {
    model?: string;
    effort?: Effort;
    context?: ContextLevel;
    extra?: ExtraContext;
}
export type ExtraContext = "brand" | "brain";
export const EXTRA_CONTEXT: ExtraContext[] = ["brand", "brain"];
export const EXTRA_LABEL: Record<ExtraContext, string> = { brand: "Add the brand in short", brain: "Add the whole brand brain" };
export type StepChoices = Record<string, StepChoice>;
